func mergePaths(old []string) []string {
    if len(old) == 0 {
        return []string{}
    }
    if slices.Contains(old, "/dev/null") {
        return []string{"/dev/null"}
    }
    dup := slices.Clone(old)
    slices.Sort(dup)
    return slices.Compact(dup)
}

static inline uint32_t pow2_ceil(uint32_t x) {
    if (x <= 1) {
        return 1;
    }
    int p = 2;
    x--;
    while (x >>= 1) {
        p <<= 1;
    }
    return p;
}

